        const originalLog = console.log;
        console.log = (...args: unknown[]) => {
          originalLog(prefixStr, ...args);
        };
        try {
          inner.render(event);
        } finally {
          console.log = originalLog;
        }
      }
    },
    newSection(label) {
      inner.newSection?.(`${prefix} ${label}`);
    },
  };
}

