// Wrap process.stdout.write for streaming content
// Track line boundaries to only prefix at start of lines
process.stdout.write = function (
  this: typeof process.stdout,
  chunk: string | Uint8Array,
  ...args: unknown[]
): boolean {
  if (typeof chunk === "string") {
    // Split by newlines but preserve them
    const parts = chunk.split(/(\n)/);
    let output = "";

    for (const part of parts) {
      if (part === "\n") {
        output += part;
        state.atLineStart = true;
      } else if (part.length > 0) {
        if (state.atLineStart) {
          output += prefixStr + part;
          state.atLineStart = false;
        } else {
          output += part;
        }
      }
    }

    // Handle different overload signatures
    if (args.length === 0) {
      return originalWrite.call(this, output);
    }
    if (args.length === 1) {
      return originalWrite.call(this, output, args[0] as BufferEncoding);
    }
    return originalWrite.call(
      this,
      output,
      args[0] as BufferEncoding,
      args[1] as (err?: Error) => void,
    );
  }

  // For Uint8Array, pass through unchanged
  if (args.length === 0) {
    return originalWrite.call(this, chunk);
  }
  if (args.length === 1) {
    return originalWrite.call(this, chunk, args[0] as (err?: Error) => void);
  }
  return originalWrite.call(
    this,
    chunk,
    args[0] as BufferEncoding,
    args[1] as (err?: Error) => void,
  );
};

